const formatFlagIndex = process.argv.indexOf('--format');
const format = formatFlagIndex === -1 ? 'text' : process.argv[formatFlagIndex + 1];

if (format === 'text') {
  console.log('ok');
} else if (format === 'json') {
  console.log(JSON.stringify({ status: 'ok' }));
} else if (format === 'csv') {
  console.log('status\nok');
} else {
  console.error('Unsupported format. Use "text", "json", or "csv".');
  process.exitCode = 1;
}

filesBeforeOracle.content:
const formatFlagIndex = process.argv.indexOf('--format');
const format = formatFlagIndex === -1 ? 'text' : process.argv[formatFlagIndex + 1];

if (format === 'text') {
  console.log('ok');
} else if (format === 'json') {
  console.log(JSON.stringify({ status: 'ok' }));
} else if (format === 'csv') {
  console.log('status\nok');
} else {
  console.error('Unsupported format. Use "text", "json", or "csv".');
  process.exitCode = 1;
}
